//#region src/engine/weekView.ts
/**
* The days from `from` on, with the real ficha of each one. Past days show what was done;
* today follows Hoje; the next gym days take the rotation in order, and when legs would
* land on the eve of a run (with that rule on) the next ficha without legs goes first.
*/
function projectDays(input, from, count) {
	const { plan, today } = input;
	const rotation = plan.rules.rotation?.length ? plan.rules.rotation : null;
	const done = input.sessions.filter((s) => s.local_date <= today);
	const sessionOn = (d) => done.find((s) => s.local_date === d);
	const runOn = (d) => input.runs.find((r) => r.local_date === d && d <= today);
	const overrideOn = (d) => input.overrides?.find((o) => o.local_date === d)?.action;
	const planned = (d) => plan.days.find((x) => x.weekday === weekday(d)) ?? null;
	/** What is planned for a day once a one-day change (rest, run) is applied. */
	const kindOn = (d) => {
		const o = overrideOn(d);
		if (o === "rest") return "rest";
		if (o === "run") return "run";
		return planned(d)?.kind ?? "rest";
	};
	let queue = rotation ? rotationQueue(rotation, done) : [];
	const rec = input.todayRec;
	if (rotation && !sessionOn(today) && rec?.kind === "gym" && rec.split_key) queue = [rec.split_key, ...queue.filter((s) => s !== rec.split_key)];
	const take = (d) => {
		if (!queue.length) return null;
		const i = plan.rules.no_legs_before_run && kindOn(addDays(d, 1)) === "run" ? queue.findIndex((s) => !splitHasLegs(s)) : 0;
		const [picked] = queue.splice(i < 0 ? 0 : i, 1);
		queue.push(picked);
		return picked;
	};
	const out = [];
	if (from > today) {
		if ((rec ? rec.kind === "gym" : kindOn(today) === "gym") && !sessionOn(today)) take(today);
		for (let d = addDays(today, 1); d < from; d = addDays(d, 1)) if (kindOn(d) === "gym") take(d);
	}
	for (let i = 0; i < count; i += 1) {
		const d = addDays(from, i);
		const p = planned(d);
		const base = {
			date: d,
			weekday: weekday(d),
			time: p?.time ?? null
		};
		const session = sessionOn(d);
		const run = runOn(d);
		if (d <= today && session) {
			out.push({
				...base,
				kind: "gym",
				split_key: session.split_key,
				run_type: null,
				state: "feito"
			});
			continue;
		}
		if (d <= today && run) {
			out.push({
				...base,
				kind: "run",
				split_key: null,
				run_type: run.run_type ?? null,
				state: "feito"
			});
			continue;
		}
		if (d < today) {
			const kind = kindOn(d);
			out.push({
				...base,
				kind,
				split_key: kind === "gym" ? p?.split_key ?? null : null,
				run_type: kind === "run" ? p?.run_type ?? "leve" : null,
				state: "passou"
			});
			continue;
		}
		if (d === today && rec) {
			const split = rec.kind === "gym" ? rotation ? take(d) : rec.split_key : null;
			out.push({
				...base,
				kind: rec.kind,
				split_key: split,
				run_type: rec.kind === "run" ? rec.run_type ?? "leve" : null,
				state: "hoje"
			});
			continue;
		}
		const kind = kindOn(d);
		out.push({
			...base,
			kind,
			split_key: kind === "gym" ? rotation ? take(d) : p?.split_key ?? null : null,
			run_type: kind === "run" ? p?.run_type ?? "leve" : null,
			state: d === today ? "hoje" : "por_vir"
		});
	}
	return out;
}
