/** Explicit allowlist: this projection cannot export notes, pain, names or email. */
function strengthResponse(data, incremental) {
	const library = new Map([...EXERCISES, ...data.exercises].map((e) => [e.id, e]));
	const legMuscles = [
		"quadriceps",
		"posterior_coxa",
		"gluteos",
		"adutores",
		"panturrilha"
	];
	const legs = (id) => {
		const e = library.get(id);
		return !!e && (e.primary_group === "pernas" || e.secondary_groups.includes("pernas") || e.muscles.some((m) => legMuscles.includes(m)));
	};
	const iso = (ms) => ms == null ? null : new Date(ms).toISOString();
	const feitas = data.sessions.filter((s) => data.changed.includes(s.id) && (incremental || s.local_date >= addDays(data.today, -13))).map((s) => {
		const sets = data.sets.filter((x) => x.session_id === s.id && !x.deleted && x.kind === "work" && x.completed_at != null && legs(x.exercise_id));
		return {
			origem_id: s.id,
			atualizado_em: iso(s.updated_at),
			apagado: s.deleted,
			data_local: s.local_date,
			inicio: iso(s.started_at),
			fim: iso(s.ended_at),
			status: s.partial ? "parcial" : "concluida",
			pernas: sets.length > 0,
			series_pernas: sets.length,
			esforco: null,
			duracao_s: s.ended_at == null ? null : Math.max(0, Math.round((s.ended_at - s.started_at) / 1e3)),
			nome: s.title.slice(0, 60)
		};
	});
	const plan = planForDay(data.plans, data.today);
	const sessions = data.sessions.filter((s) => !s.deleted);
	const planejadas = (plan ? projectDays({
		plan,
		today: data.today,
		sessions,
		runs: [],
		overrides: data.overrides
	}, data.today, 14) : []).filter((d) => d.kind === "gym" || data.overrides.some((o) => o.local_date === d.date && o.action === "rest") && plan?.days.some((p) => p.weekday === d.weekday && p.kind === "gym")).map((d) => {
		const plannedSplit = plan?.days.find((p) => p.weekday === d.weekday)?.split_key;
		const split = d.split_key ?? plannedSplit;
		const routine = data.routines.find((r) => r.split_key === split && r.origin === "plano") ?? data.routines.find((r) => r.split_key === split);
		return {
			data_local: d.date,
			nome: (routine?.name ?? (split ? splitLabel(split) : "Treino")).slice(0, 60),
			pernas: !!routine && data.routine_items.some((i) => i.routine_id === routine.id && legs(i.exercise_id)),
			status: d.state === "feito" ? "feito" : d.kind === "rest" ? "pulado" : split !== plannedSplit && !plan?.rules.rotation ? "movido" : "planejado"
		};
	});
	return {
		versao: 1,
		cursor: data.cursor,
		feitas,
		planejadas
	};
}
//#endregion
export { strengthResponse };
